import requests
from taf.sw.security.defensics.clients.exceptions import ConnectionFailed, RequestFailed


class DefensicsHttpClient(object):
    _URL_TEMPLATE = "{protocol}://{ip}:{port}"

    def __init__(self, ip_address, port, token, secure):
        self.ip_address = ip_address
        self.port = port
        self.token = token
        if secure:
            self.http_protocol = "https"
        else:
            self.http_protocol = "http"
        self.api_url = self._URL_TEMPLATE.format(
            protocol=self.http_protocol,
            ip=self.ip_address,
            port=self.port,
        )

    def send(self, method, url, parameters, timeout, data=None):
        response = self._send(method, parameters, timeout, data, url)
        response = self._handle_response(response=response)
        return response.text

    def send_and_return_response(self, method, url, parameters, timeout, data=None):
        response = self._send(method, parameters, timeout, data, url)
        return self._handle_response(response=response)

    def _send(self, method, parameters, timeout, data, url):
        if self.token:
            headers = {"Authorization": f"token {self.token}"}
        else:
            headers = {}
        request_url = self.api_url + url
        try:
            if method == "GET":
                response = requests.get(url=request_url, params=parameters, headers=headers, timeout=timeout)
            elif method == "POST":
                response = requests.post(
                    url=request_url, params=parameters, headers=headers, timeout=timeout, data=data
                )
            else:
                raise ValueError("HTTP method must be `GET` or `POST`.")
        except requests.exceptions.RequestException as rq_e:
            raise ConnectionFailed(f"Client connection to endpoint failed with error {rq_e}")
        return response

    @staticmethod
    def _handle_response(response):
        if response.status_code != requests.codes.ok:
            err_msg = "Client request failed with status {status} and message {msg}"
            raise RequestFailed(err_msg.format(status=response.status_code, msg=response.text))
        return response
